def verify_costas(perm):
    n = len(perm)
    diffs = set()
    for i in range(n):
        for j in range(i+1, n):
            dc = j - i
            dr = perm[j] - perm[i]
            if (dc, dr) in diffs:
                return False, (dc, dr)
            diffs.add((dc, dr))
    return True, None

perm = [0, 2, 11, 6, 3, 8, 9, 7, 10, 1, 5, 4, 12]
print("Fixed check: x[4]=", perm[4], "x[9]=", perm[9])
ok, dup = verify_costas(perm)
print("Costas property:", ok)
if not ok:
    print("Duplicate:", dup)
print("Number of diffs:", len(perm)*(len(perm)-1)//2)
